from dataclasses import dataclass


@dataclass
class Rect:
    w: int
    h: int


@dataclass
class Square:
    side: int


@dataclass
class Tri:
    b: int
    h: int


Shape = Rect | Square | Tri


def area(s: Shape) -> int:
    """Area of the shape, rounded down to an int.

    Rect: w*h. Square: side*side. Tri: b*h/2 (floor division).
    """
    if isinstance(s, Rect):
        return s.w * s.h
    if isinstance(s, Square):
        return s.side * s.side
    return s.b * s.h // 2


def test_rect() -> None:
    assert area(Rect(3, 4)) == 12


def test_rect_zero() -> None:
    assert area(Rect(0, 5)) == 0


def test_square() -> None:
    assert area(Square(5)) == 25


def test_square_zero() -> None:
    assert area(Square(0)) == 0


def test_tri_even() -> None:
    assert area(Tri(4, 6)) == 12


def test_tri_rounds_down() -> None:
    assert area(Tri(3, 5)) == 7


def test_tri_one_by_one() -> None:
    assert area(Tri(1, 1)) == 0


def test_tri_zero() -> None:
    assert area(Tri(0, 9)) == 0


def test_large_values() -> None:
    assert area(Tri(10**12 + 1, 10**12 + 1)) == (10**12 + 1) ** 2 // 2

